/* Shared persistent wardrobe used by the host, fitting and journal. */
(()=>{
 const categories=['套装','上衣','裤子','外套','内搭','鞋子','配饰'];let cache=[],queue=Promise.resolve();
 function normalize(x){if(!x)throw Error('衣物数据无效');const category=({'半身裙':'裤子','下装':'裤子','连衣裙':'套装','包':'配饰'})[x.category]||x.category;if(typeof x.id!=='string'||typeof x.name!=='string'||!categories.includes(category)||!/^data:image\/(png|jpeg|webp);base64,/.test(x.image)||x.image.length>8*1024*1024)throw Error('衣物数据格式不正确');return {id:x.id,name:x.name.slice(0,100),category,image:x.image,purchased:x.purchased!==false}}
 const database=()=>new Promise((resolve,reject)=>{const r=indexedDB.open('ootrip-html-demo-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('garments',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('衣橱存储无法打开'))});
 async function readRaw(){const db=await database();try{return await new Promise((resolve,reject)=>{const r=db.transaction('garments').objectStore('garments').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}finally{db.close()}}
 async function writeRaw(items,remove=false,replace=false){const db=await database();try{await new Promise((resolve,reject)=>{const tx=db.transaction('garments','readwrite'),store=tx.objectStore('garments');if(replace)store.clear();for(const x of items)remove?store.delete(x.id):store.put(x);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}finally{db.close()}}
 function publish(){window.dispatchEvent(new CustomEvent('ootrip:wardrobe-changed',{detail:cache.slice()}));if(location.protocol==='http:'&&window.opener)window.opener.postMessage({type:'ootrip:wardrobe-mirror',items:cache},'*')}
 const ready=(async()=>{cache=(await readRaw()).map(normalize);if(!cache.length&&!localStorage.getItem('ootrip-wardrobe-initialized')){const extras=typeof outfitGarmentImages==='undefined'?[]:outfitGarmentImages.map((image,i)=>({id:'outfit-example-'+i,name:['长款风衣','白色针织衫','浅蓝衬衫','蓝色牛仔裤','手提包','运动鞋'][i],category:['外套','上衣','上衣','裤子','配饰','鞋子'][i],image,purchased:true}));cache=[...(window.OOTRIP_WARDROBE_SEED||[]),...extras].map(normalize);await writeRaw(cache)}localStorage.setItem('ootrip-wardrobe-initialized','1');return cache})();
 window.OotripWardrobe={ready,get cache(){return cache.slice()},async read(){await ready;await queue;cache=(await readRaw()).map(normalize);return cache.slice()},save(items,remove=false){const values=items.map(normalize);queue=queue.catch(()=>{}).then(async()=>{await ready;await writeRaw(values,remove);cache=(await readRaw()).map(normalize);publish()});return queue},replace(items){const values=items.map(normalize);queue=queue.catch(()=>{}).then(async()=>{await ready;await writeRaw(values,false,true);cache=values;publish()});return queue},async importFile(file,category){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||!file.size||file.size>5*1024*1024)throw Error('请选择 5 MB 以内的 PNG、JPEG 或 WebP 图片');const image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const item=normalize({id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,'')||'我的衣物',category,image,purchased:true});await this.save([item]);return item}};
 ready.catch(()=>{});
})();
